void escape_vim_pattern(char *pattern) {
    // Escape special characters in the regular expression pattern
    // This is a simplified example; you may need to adjust it based on your specific use case
    char escaped_pattern[256];
    int i = 0;
    for (char c : *pattern) {
        if (c == '\\' || c == '^' || c == '$' || c == '*' || c == '+' || c == '|' || c == ']' || c == '[') {
            escaped_pattern[i++] = '\\';
            i++;
        } else if (c == '\n' || c == '\r' || c == '\t' || c == '\f' || c == '\v') {
            escaped_pattern[i++] = '\\n';
            i++;
        } else {
            escaped_pattern[i++] = c;
        }
    }
    // Copy the escaped pattern to the original pattern buffer
    strcpy(pattern, escaped_pattern, sizeof(escaped_pattern));
}
